//! Safe-ish wrapper over `GothicKit/dmusic`.
//!
//! The wrapper owns the C objects and exposes only the operations needed to
//! load a segment, switch themes and render PCM. Raw pointers never leave this
//! crate.
//!
//! `src/bindings.rs` is generated by the `xtask` binary and committed. The
//! library build only compiles the vendored C sources.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]

#[allow(dead_code)]
mod bindings;

use std::ffi::{CStr, CString};
use std::fmt;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::ptr::{self, NonNull};

pub use bindings::{
    DmEmbellishmentType, DmLoaderOptions, DmLogLevel, DmRenderOptions, DmResult, DmTiming,
};

use bindings::{DmLoader, DmPerformance, DmSegment};

/// Error returned by a `dmusic` call.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct DmError(pub DmResult::Type);

impl DmError {
    pub fn code(self) -> DmResult::Type {
        self.0
    }

    pub fn is_not_found(self) -> bool {
        self.0 == DmResult::NOT_FOUND
    }
}

impl fmt::Debug for DmError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_tuple("DmError").field(&self.0).finish()
    }
}

impl fmt::Display for DmError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self.0 {
            DmResult::INVALID_ARGUMENT => "invalid argument",
            DmResult::INVALID_STATE => "invalid state",
            DmResult::MEMORY_EXHAUSTED => "memory exhausted",
            DmResult::NOT_FOUND => "not found",
            DmResult::FILE_CORRUPT => "file corrupt",
            DmResult::MUTEX_ERROR => "mutex error",
            _ => "unknown error",
        };
        write!(f, "dmusic: {name} ({})", self.0)
    }
}

impl std::error::Error for DmError {}

fn check(result: DmResult::Type) -> Result<(), DmError> {
    if result == DmResult::SUCCESS {
        Ok(())
    } else {
        Err(DmError(result))
    }
}

/// Installs the built-in stderr logger at the given level.
pub fn set_logger_default(level: DmLogLevel::Type) {
    // SAFETY: the C logger state is process-global and only written here.
    unsafe { bindings::Dm_setLoggerDefault(level) };
}

/// Changes the level of the currently installed logger.
pub fn set_logger_level(level: DmLogLevel::Type) {
    // SAFETY: the C logger state is process-global and only written here.
    unsafe { bindings::Dm_setLoggerLevel(level) };
}

type Resolver = dyn Fn(&str) -> Option<Vec<u8>> + Send + Sync + 'static;

struct ResolverCtx {
    resolve: Box<Resolver>,
}

unsafe extern "C" fn resolve_trampoline(
    ctx: *mut core::ffi::c_void,
    file: *const core::ffi::c_char,
    len: *mut usize,
) -> *mut core::ffi::c_void {
    if ctx.is_null() || file.is_null() || len.is_null() {
        return ptr::null_mut();
    }

    // A panic must not cross the C boundary.
    let bytes = catch_unwind(AssertUnwindSafe(|| {
        // SAFETY: `ctx` points at the `ResolverCtx` owned by the loader and
        // `file` is a valid C string for the duration of the call.
        let ctx = unsafe { &*ctx.cast::<ResolverCtx>() };
        let name = unsafe { CStr::from_ptr(file) }.to_str().ok()?;
        (ctx.resolve)(name)
    }))
    .ok()
    .flatten();

    let Some(bytes) = bytes else {
        return ptr::null_mut();
    };
    if bytes.is_empty() {
        return ptr::null_mut();
    }

    // SAFETY: the loader takes ownership of this allocation and releases it
    // with the default `free` allocator.
    let memory = unsafe { libc::malloc(bytes.len()) }.cast::<u8>();
    if memory.is_null() {
        return ptr::null_mut();
    }
    // SAFETY: both buffers are valid for `bytes.len()` bytes and do not overlap.
    unsafe { ptr::copy_nonoverlapping(bytes.as_ptr(), memory, bytes.len()) };
    // SAFETY: `len` was checked for null.
    unsafe { *len = bytes.len() };
    memory.cast()
}

/// Segment loader and cache for styles and DLS collections.
pub struct Loader {
    ptr: NonNull<DmLoader>,
    // Boxed so the context pointer handed to the C loader stays valid when the
    // vector grows.
    #[allow(clippy::vec_box)]
    _resolvers: Vec<Box<ResolverCtx>>,
}

// SAFETY: the C loader documents its operations as thread-safe; the resolver
// closures are `Send + Sync`.
unsafe impl Send for Loader {}
unsafe impl Sync for Loader {}

impl Loader {
    /// Creates a loader. With `download`, referenced styles and DLS
    /// collections are resolved automatically by [`Loader::segment`].
    pub fn new(download: bool) -> Result<Self, DmError> {
        let mut raw = ptr::null_mut();
        let options: DmLoaderOptions::Type = if download {
            DmLoaderOptions::DOWNLOAD
        } else {
            DmLoaderOptions::DEFAULT
        };
        // SAFETY: `raw` is a valid out pointer.
        check(unsafe { bindings::DmLoader_create(&mut raw, options) })?;
        let Some(ptr) = NonNull::new(raw) else {
            return Err(DmError(DmResult::MEMORY_EXHAUSTED));
        };
        Ok(Self {
            ptr,
            _resolvers: Vec::new(),
        })
    }

    /// Adds a lookup called for every file referenced by a segment. The
    /// returned bytes are copied into memory owned by the loader.
    pub fn add_resolver<F>(&mut self, resolve: F) -> Result<(), DmError>
    where
        F: Fn(&str) -> Option<Vec<u8>> + Send + Sync + 'static,
    {
        let mut ctx = Box::new(ResolverCtx {
            resolve: Box::new(resolve),
        });
        let ctx_ptr = ptr::from_mut(ctx.as_mut()).cast::<core::ffi::c_void>();
        // SAFETY: the loader keeps `ctx_ptr` and calls the trampoline with it.
        // The box is kept alive in `_resolvers` until the loader is released.
        check(unsafe {
            bindings::DmLoader_addResolver(self.ptr.as_ptr(), Some(resolve_trampoline), ctx_ptr)
        })?;
        self._resolvers.push(ctx);
        Ok(())
    }

    /// Loads and (when enabled) downloads a segment. The returned segment is
    /// independent of the loader and releases itself on drop.
    pub fn segment(&self, name: &str) -> Result<Segment, DmError> {
        let name = CString::new(name).map_err(|_| DmError(DmResult::INVALID_ARGUMENT))?;
        let mut raw = ptr::null_mut();
        // SAFETY: `name` is a valid C string and `raw` is a valid out pointer.
        check(unsafe {
            bindings::DmLoader_getSegment(self.ptr.as_ptr(), name.as_ptr(), &mut raw)
        })?;
        let Some(ptr) = NonNull::new(raw) else {
            return Err(DmError(DmResult::MEMORY_EXHAUSTED));
        };
        Ok(Segment { ptr })
    }
}

impl Drop for Loader {
    fn drop(&mut self) {
        // SAFETY: this loader is owned and released exactly once.
        unsafe { bindings::DmLoader_release(self.ptr.as_ptr()) };
    }
}

/// A loaded DirectMusic segment.
pub struct Segment {
    ptr: NonNull<DmSegment>,
}

// SAFETY: a downloaded segment is immutable; the C API retains segments
// internally when they are scheduled for playback.
unsafe impl Send for Segment {}
unsafe impl Sync for Segment {}

impl Segment {
    pub fn name(&self) -> Option<String> {
        // SAFETY: the segment is alive for the duration of the call.
        let name = unsafe { bindings::DmSegment_getName(self.ptr.as_ptr()) };
        if name.is_null() {
            return None;
        }
        // SAFETY: the C API returns a valid NUL-terminated string.
        Some(
            unsafe { CStr::from_ptr(name) }
                .to_string_lossy()
                .into_owned(),
        )
    }

    /// Length of one repeat in seconds.
    pub fn length(&self) -> f64 {
        // SAFETY: the segment is alive for the duration of the call.
        unsafe { bindings::DmSegment_getLength(self.ptr.as_ptr()) }
    }

    pub fn repeats(&self) -> u32 {
        // SAFETY: the segment is alive for the duration of the call.
        unsafe { bindings::DmSegment_getRepeats(self.ptr.as_ptr()) }
    }
}

impl Drop for Segment {
    fn drop(&mut self) {
        // SAFETY: this segment is owned and released exactly once.
        unsafe { bindings::DmSegment_release(self.ptr.as_ptr()) };
    }
}

/// Persistent DirectMusic performance.
pub struct Performance {
    ptr: NonNull<DmPerformance>,
}

// SAFETY: the C performance uses an internal mutex and supports control calls
// from a different thread than rendering.
unsafe impl Send for Performance {}
unsafe impl Sync for Performance {}

impl Performance {
    /// Creates a performance rendering at `sample_rate` (`0` selects 44100).
    pub fn new(sample_rate: u32) -> Result<Self, DmError> {
        let mut raw = ptr::null_mut();
        // SAFETY: `raw` is a valid out pointer.
        check(unsafe { bindings::DmPerformance_create(&mut raw, sample_rate) })?;
        let Some(ptr) = NonNull::new(raw) else {
            return Err(DmError(DmResult::MEMORY_EXHAUSTED));
        };
        Ok(Self { ptr })
    }

    /// Starts a segment at the given timing boundary, stopping the current one.
    pub fn play_segment(
        &self,
        segment: Option<&Segment>,
        timing: DmTiming::Type,
    ) -> Result<(), DmError> {
        let segment = segment.map_or(ptr::null_mut(), |segment| segment.ptr.as_ptr());
        // SAFETY: both pointers are valid; the performance retains the segment.
        check(unsafe { bindings::DmPerformance_playSegment(self.ptr.as_ptr(), segment, timing) })
    }

    /// Schedules a transition to `segment` using a pattern from the currently
    /// playing segment. With no current segment this starts `segment`
    /// directly.
    pub fn play_transition(
        &self,
        segment: &Segment,
        embellishment: DmEmbellishmentType::Type,
        timing: DmTiming::Type,
    ) -> Result<(), DmError> {
        // SAFETY: both pointers are valid; the performance retains the segment.
        check(unsafe {
            bindings::DmPerformance_playTransition(
                self.ptr.as_ptr(),
                segment.ptr.as_ptr(),
                embellishment,
                timing,
            )
        })
    }

    /// Stops playback at the next instant.
    pub fn stop(&self) -> Result<(), DmError> {
        self.play_segment(None, DmTiming::INSTANT)
    }

    /// Renders interleaved stereo `i16` samples, filling the whole buffer.
    pub fn render_stereo(&self, out: &mut [i16]) -> Result<(), DmError> {
        if !out.len().is_multiple_of(2) {
            return Err(DmError(DmResult::INVALID_ARGUMENT));
        }
        let opts: DmRenderOptions::Type = DmRenderOptions::SHORT | DmRenderOptions::STEREO;
        // SAFETY: `out` is valid for `out.len()` `i16` values and the C API
        // writes exactly that many.
        check(unsafe {
            bindings::DmPerformance_renderPcm(
                self.ptr.as_ptr(),
                out.as_mut_ptr().cast(),
                out.len(),
                opts,
            )
        })
    }

    /// Output volume in `[0, 1]`.
    pub fn set_volume(&self, volume: f32) {
        // SAFETY: the performance is alive and the call is thread-safe.
        unsafe { bindings::DmPerformance_setVolume(self.ptr.as_ptr(), volume) };
    }
}

impl Drop for Performance {
    fn drop(&mut self) {
        // SAFETY: this performance is owned and released exactly once.
        unsafe { bindings::DmPerformance_release(self.ptr.as_ptr()) };
    }
}
